#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>
using namespace std;

static string expected(int n) {
    string s;
    for (int i = 0; i < 26; ++i) s += static_cast<char>('A' + (i + n) % 26);
    return s;
}

static bool check(const string& exe, int n, int id) {
    const string inFile = "l3a2406p1_in.txt", outFile = "l3a2406p1_out.txt";
    { ofstream out(inFile); out << n << '\n'; }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string actual;
    getline(in, actual);
    string extra;
    bool extraLine = static_cast<bool>(getline(in, extra));
    const string want = expected(n);
    bool ok = code == 0 && !extraLine && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": n=" << n << ", expected=" << want
                  << ", actual=" << actual << ", process status=" << code << '\n';
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<int> tests = {3, 1, 2, 25, 26, 27, 51, 52, 99, 100};
    unsigned seed = 202406u;
    for (int trial = 0; trial < 10; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        tests.push_back(static_cast<int>(seed % 100u) + 1);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

