#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>
using namespace std;

static string expected(const vector<vector<long long>>& groups) {
    string out;
    for (const auto& a : groups) {
        long long mx = 0;
        for (long long x : a) mx = max(mx, x);
        bool ok = true;
        for (long long x : a) if (mx % x) { ok = false; break; }
        out += ok ? "Yes\n" : "No\n";
    }
    return out;
}

static bool check(const string& exe, const vector<vector<long long>>& groups, int id) {
    const string inFile = "l3a2406p2_in.txt", outFile = "l3a2406p2_out.txt";
    {
        ofstream out(inFile);
        out << groups.size() << '\n';
        for (const auto& a : groups) {
            out << a.size() << '\n';
            for (size_t i = 0; i < a.size(); ++i) out << a[i] << (i + 1 == a.size() ? '\n' : ' ');
        }
    }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    const string want = expected(groups);
    bool ok = code == 0 && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": expected=" << want << " actual=" << actual
                  << " process status=" << code << '\n';
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<vector<vector<long long>>> tests = {
        {{1, 2, 4}, {1, 2, 3, 4, 5}},
        {{1}}, {{7}}, {{2, 4}}, {{4, 2}}, {{2, 3}}, {{6, 2, 3}}, {{6, 4, 3}},
        {{1000000000, 1000000000}}, {{999999999, 3}}, {{999999999, 2}},
        {{1, 1, 1, 1}}, {{12, 4, 6}}, {{12, 4, 5}}
    };
    {
        vector<long long> all1(100000, 1);
        tests.push_back({all1});
    }
    {
        vector<long long> a(100000, 2);
        a[50000] = 3;
        tests.push_back({a});
    }
    {
        vector<long long> a(100000, 7);
        a[0] = 1000000000;
        tests.push_back({a});
    }
    {
        vector<long long> a(99999, 5);
        a.push_back(1000000000);
        tests.push_back({a});
    }
    unsigned seed = 202406u;
    for (int trial = 0; trial < 6; ++trial) {
        vector<vector<long long>> g;
        int t = 1 + trial % 3;
        for (int gi = 0; gi < t; ++gi) {
            int n = 2 + static_cast<int>(seed % 50u);
            seed = seed * 1664525u + 1013904223u;
            vector<long long> a;
            for (int i = 0; i < n; ++i) {
                seed = seed * 1664525u + 1013904223u;
                a.push_back(static_cast<long long>(seed % 1000000000u) + 1);
            }
            g.push_back(a);
        }
        tests.push_back(g);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
